1	/**
2	 * @module templates/aspire/helpers/generate-register-background_test
3	 *
4	 * Executes the emitted background-registration helper against narrow Aspire
5	 * doubles so declared service and plugin reference behavior is tested at the
6	 * generated-module boundary.
7	 */
8	
9	import { assert, assertEquals, assertRejects, assertStringIncludes } from 'jsr:@std/assert@^1';
10	import { describe, it } from 'jsr:@std/testing@^1/bdd';
11	import { toFileUrl } from 'jsr:@std/path@^1';
12	import type { BackgroundProcessorEntry, NetScriptConfig } from '@netscript/aspire/types';
13	import { createServerServiceEnvKey } from '../../../../../../../sdk/src/discovery/service-url.ts';
14	import { generateRegisterBackground } from '../register/generate-register-background.ts';
15	import { DEFAULT_TEMPLATE_REGISTRY } from '../../../../application/registries/template-registry.ts';
16	import { EMPTY_CONFIG, MINIMAL_DENO_DEFAULTS } from './generators-test-support.ts';
17	
18	await DEFAULT_TEMPLATE_REGISTRY.hydrate();
19	
20	const PROCESSOR_NAME = 'notifications';
21	const REFERENCE_NAME = 'workers-api';
22	const REFERENCE_ENDPOINT = 'http://127.0.0.1:43123';
23	const DISCOVERY_KEY = 'services__workers-api__http__0';
24	const SOURCE_SAFE_NAMES = [
25	  "it's",
26	  String.raw`back\slash`,
27	  'tick`name',
28	  'workers-api',
29	  'workers_api',
30	  'class',
31	  'await',
32	  'function',
33	  'const',
34	  'line\u2028separator',
35	] as const;
36	
37	interface EndpointResource {
38	  getEndpoint(name: string): Promise<string | undefined>;
39	}
40	
41	interface RecordingResource extends EndpointResource {
42	  readonly environment: Array<readonly [string, unknown]>;
43	  withEnvironment(key: string, value: unknown): Promise<RecordingResource>;
44	}
45	
46	interface RecordingBuilder {
47	  readonly registrations: string[];
48	  addExecutable(
49	    name: string,
50	    command: string,
51	    workdir: string,
52	    args: string[],
53	  ): RecordingResource;
54	}
55	
56	interface GeneratedBackgroundModule {
57	  registerBackgroundProcessors(
58	    builder: RecordingBuilder,
59	    config: NetScriptConfig,
60	    infrastructure: Record<string, never>,
61	    services: Map<string, EndpointResource>,
62	    plugins: Map<string, EndpointResource>,
63	    appHostDir: string,
64	  ): Promise<Map<string, RecordingResource>>;
65	}
66	
67	function backgroundEntry(
68	  references: Pick<BackgroundProcessorEntry, 'ServiceReferences' | 'PluginReferences'>,
69	): BackgroundProcessorEntry {
70	  return {
71	    Enabled: true,
72	    Runtime: 'deno',
73	    Entrypoint: 'bin/notifications.ts',
74	    Telemetry: false,
75	    WatchMode: false,
76	    RequiresDb: false,
77	    RequiresKv: false,
78	    ...references,
79	  };
80	}
81	
82	function configForProcessors(
83	  processors: Record<string, BackgroundProcessorEntry>,
84	): NetScriptConfig {
85	  return {
86	    ...EMPTY_CONFIG,
87	    BackgroundProcessors: processors,
88	  };
89	}
90	
91	function configFor(entry: BackgroundProcessorEntry): NetScriptConfig {
92	  return configForProcessors({ [PROCESSOR_NAME]: entry });
93	}
94	
95	function endpointResource(endpoint: string | undefined): EndpointResource {
96	  return {
97	    getEndpoint: (_name: string): Promise<string | undefined> => Promise.resolve(endpoint),
98	  };
99	}
100	
101	function createRecordingBuilder(): RecordingBuilder {
102	  const registrations: string[] = [];
103	  return {
104	    registrations,
105	    addExecutable(name: string): RecordingResource {
106	      registrations.push(name);
107	      const environment: Array<readonly [string, unknown]> = [];
108	      return {
109	        environment,
110	        getEndpoint: (_endpointName: string): Promise<string | undefined> =>
111	          Promise.resolve(undefined),
112	        withEnvironment(key: string, value: unknown): Promise<RecordingResource> {
113	          environment.push([key, value]);
114	          return Promise.resolve(this);
115	        },
116	      };
117	    },
118	  };
119	}
120	
121	function isGeneratedBackgroundModule(value: unknown): value is GeneratedBackgroundModule {
122	  return typeof value === 'object' && value !== null &&
123	    'registerBackgroundProcessors' in value &&
124	    typeof value.registerBackgroundProcessors === 'function';
125	}
126	
127	async function loadGeneratedModule(
128	  processors: Record<string, BackgroundProcessorEntry>,
129	): Promise<{ module: GeneratedBackgroundModule; dispose: () => Promise<void> }> {
130	  const root = await Deno.makeTempDir({ prefix: 'ns-1371-background-' });
131	  const helpersDir = `${root}/.helpers`;
132	  const sdkDir = `${root}/.aspire/modules`;
133	  await Deno.mkdir(helpersDir, { recursive: true });
134	  await Deno.mkdir(sdkDir, { recursive: true });
135	
136	  await Deno.writeTextFile(
137	    `${sdkDir}/aspire.mts`,
138	    [
139	      `export const OtlpProtocol = { HttpProtobuf: 'http/protobuf' } as const;`,
140	      `export interface ExecutableResource {`,
141	      `  getEndpoint(name: string): Promise<string | undefined>;`,
142	      `  withEnvironment(key: string, value: unknown): Promise<ExecutableResource>;`,
143	      `}`,
144	      `export interface DistributedApplicationBuilder {`,
145	      `  addExecutable(name: string, command: string, workdir: string, args: string[]): ExecutableResource;`,
146	      `}`,
147	      ``,
148	    ].join('\n'),
149	  );
150	  await Deno.writeTextFile(
151	    `${helpersDir}/_aspire-compat.mts`,
152	    [
153	      `export function buildDatabaseUriEnvKey(): undefined { return undefined; }`,
154	      `export function buildDatabaseProviderEnvVars(): Record<string, string> { return {}; }`,
155	      `export function buildSqliteDatabaseUrl(): string { return 'file:unused'; }`,
156	      `export function buildOtelEnvVars(): Record<string, string> { return {}; }`,
157	      `export function resolvePermissions(): string[] { return []; }`,
158	      `export function resolveWorkspacePath(root: string, relative: string): string { return root + '/' + relative; }`,
159	      `export async function withCacheReference<T>(resource: T): Promise<T> { return await Promise.resolve(resource); }`,
160	      ``,
161	    ].join('\n'),
162	  );
163	  await Deno.writeTextFile(
164	    `${helpersDir}/register-infrastructure.mts`,
165	    `export interface InfrastructureContext {}\n`,
166	  );
167	
168	  const generatedPath = `${helpersDir}/register-background.mts`;
169	  await Deno.writeTextFile(
170	    generatedPath,
171	    generateRegisterBackground({
172	      processors,
173	      version: EMPTY_CONFIG.Version,
174	      denoDefaults: MINIMAL_DENO_DEFAULTS,
175	    }),
176	  );
177	
178	  try {
179	    const namespace: unknown = await import(toFileUrl(generatedPath).href);
180	    assert(
181	      isGeneratedBackgroundModule(namespace),
182	      'the generated helper did not export registerBackgroundProcessors',
183	    );
184	    return {
185	      module: namespace,
186	      dispose: () => Deno.remove(root, { recursive: true }),
187	    };
188	  } catch (error) {
189	    await Deno.remove(root, { recursive: true });
190	    throw error;
191	  }
192	}
193	
194	async function runGeneratedRegistration(
195	  entry: BackgroundProcessorEntry,
196	  services: Map<string, EndpointResource>,
197	  plugins: Map<string, EndpointResource>,
198	  builder: RecordingBuilder,
199	): Promise<Map<string, RecordingResource>> {
200	  const loaded = await loadGeneratedModule({ [PROCESSOR_NAME]: entry });
201	  try {
202	    return await loaded.module.registerBackgroundProcessors(
203	      builder,
204	      configFor(entry),
205	      {},
206	      services,
207	      plugins,
208	      '/apphost',
209	    );
210	  } finally {
211	    await loaded.dispose();
212	  }
213	}
214	
215	async function assertGeneratedModuleLoads(
216	  processors: Record<string, BackgroundProcessorEntry>,
217	): Promise<void> {
218	  const loaded = await loadGeneratedModule(processors);
219	  await loaded.dispose();
220	}
221	
222	function configurationError(kind: 'service' | 'plugin'): string {
223	  return `Background processor configuration error: '${PROCESSOR_NAME}' could not resolve ${kind} reference '${REFERENCE_NAME}' HTTP endpoint.`;
224	}
225	
226	function assignedValue(resource: RecordingResource, key: string): unknown {
227	  return resource.environment.find(([candidate]) => candidate === key)?.[1];
228	}
229	
230	describe('generateRegisterBackground declared references (#1371)', () => {
231	  it('parses every source-sensitive processor-name spelling', async () => {
232	    await assertGeneratedModuleLoads(
233	      Object.fromEntries(SOURCE_SAFE_NAMES.map((name) => [name, backgroundEntry({})])),
234	    );
235	  });
236	
237	  it('parses and executes reserved and normalization-collision processor names', async () => {
238	    const names = ['class', 'await', 'function', 'const', 'workers-api', 'workers_api'] as const;
239	    const processors = Object.fromEntries(names.map((name) => [name, backgroundEntry({})]));
240	    const loaded = await loadGeneratedModule(processors);
241	    const builder = createRecordingBuilder();
242	    try {
243	      const registered = await loaded.module.registerBackgroundProcessors(
244	        builder,
245	        configForProcessors(processors),
246	        {},
247	        new Map(),
248	        new Map(),
249	        '/apphost',
250	      );
251	      assertEquals(builder.registrations, [...names]);
252	      assertEquals([...registered.keys()], [...names]);
253	    } finally {
254	      await loaded.dispose();
255	    }
256	  });
257	
258	  it('parses quote, backslash, and backtick entry literals', async () => {
259	    await assertGeneratedModuleLoads({
260	      [PROCESSOR_NAME]: {
