1	/**
2	 * @module
3	 *
4	 * Generator for `.helpers/register-background.mts` — registers background
5	 * processors (workers, sagas, triggers, benchmark) with the Aspire SDK
6	 * builder via `addExecutable()`.
7	 *
8	 * Each processor is registered using the CommunityToolkit beta NuGet's
9	 * `addExecutable(name, 'deno', workdir, ['run', ...perms, entrypoint])` method.
10	 * Telemetry-enabled entries receive the full executable OTEL env set via
11	 * `buildOtelEnvVars`; telemetry-disabled entries (e.g., benchmark) receive
12	 * explicit opt-out vars instead.
13	 *
14	 * Background processors do NOT cross-reference each other, so no two-pass
15	 * registration is needed.
16	 */
17	
18	import type { RegisterBackgroundOptions } from '../types.ts';
19	import { extractSagaStoreBackend, fileHeader } from '../_utils.ts';
20	import { SCAFFOLD_ASPIRE_MODULES } from '../../../../constants/scaffold/scaffold-aspire.ts';
21	import { RESOURCE_DEFAULTS } from '@netscript/aspire/constants';
22	import { TEMPLATE_KEYS } from '../../../../assets/manifest.ts';
23	import { renderTemplateAssetSync } from '../../../../adapters/templates/template-asset.ts';
24	import { withDatabasePermissions } from './database-permissions.ts';
25	
26	/**
27	 * Generates the register-background.mts file content.
28	 *
29	 * @param options - Background processor entries, version, and Deno defaults from parsed config
30	 * @returns Generated TypeScript source as a string
31	 */
32	export function generateRegisterBackground(options: RegisterBackgroundOptions): string {
33	  const { processors, version: _version, denoDefaults, databaseEngine } = options;
34	  const entries = Object.entries(processors);
35	
36	  const registrationBlocks: string[] = [];
37	
38	  for (const [processorIndex, [name, entry]] of entries.entries()) {
39	    const id = `bg_${processorIndex}`;
40	    const workdir = entry.Workdir ?? '.';
41	    const entrypoint = entry.Entrypoint ?? `${name}/runtime.ts`;
42	    const telemetry = entry.Telemetry !== false;
43	    const watchMode = entry.WatchMode ?? false;
44	    const entryPermissions = entry.Permissions
45	      ? withDatabasePermissions(entry.Permissions, databaseEngine)
46	      : undefined;
47	    const defaultPermissions = entryPermissions
48	      ? denoDefaults.Permissions
49	      : withDatabasePermissions(denoDefaults.Permissions, databaseEngine);
50	    const serviceRefs = [
51	      ...(entry.ServiceReferences ?? []),
52	    ];
53	    const pluginRefs = entry.PluginReferences ?? [];
54	
55	    const lines: string[] = [];
56	    lines.push(`  // --- processor ${processorIndex} ---`);
57	
58	    // Skip disabled entries
59	    lines.push(
60	      `  if (config.BackgroundProcessors[${JSON.stringify(name)}]?.Enabled !== false) {`,
61	    );
62	
63	    // Resolve permissions — background uses --watch (NOT --watch-hmr)
64	    lines.push(`    const ${id}_perms = resolvePermissions(`);
65	    if (entryPermissions) {
66	      lines.push(`      ${JSON.stringify(entryPermissions)},`);
67	    } else {
68	      lines.push(`      undefined,`);
69	    }
70	    lines.push(`      ${JSON.stringify(defaultPermissions)},`);
71	    lines.push(`      ${watchMode},`);
72	    lines.push(`      '${RESOURCE_DEFAULTS.WatchFlag}',`);
73	    lines.push(`    );`);
74	
75	    // Resolve working directory
76	    lines.push(
77	      `    const ${id}_workdir = resolveWorkspacePath(appHostDir, ${JSON.stringify(workdir)});`,
78	    );
79	    lines.push(
80	      `    const ${id}_bootstrapModule = new URL('../../services/_shared/plugin-service-context.ts', import.meta.url).href;`,
81	    );
82	
83	    // Resolve every declared reference before registering the processor. A
84	    // declared reference is required configuration, so missing resources and
85	    // resources without an HTTP endpoint are equally fatal.
86	    if (serviceRefs.length > 0 || pluginRefs.length > 0) {
87	      lines.push(``);
88	      lines.push(`    // Declared reference preflight — fail before processor registration`);
89	      for (const [index, ref] of serviceRefs.entries()) {
90	        const endpointId = `ref_service_${processorIndex}_${index}`;
91	        const message =
92	          `Background processor configuration error: '${name}' could not resolve service reference '${ref}' HTTP endpoint.`;
93	        lines.push(
94	          `    const ${endpointId} = await _services.get(${
95	            JSON.stringify(ref)
96	          })?.getEndpoint('http');`,
97	        );
98	        lines.push(`    if (!${endpointId}) {`);
99	        lines.push(`      throw new Error(${JSON.stringify(message)});`);
100	        lines.push(`    }`);
101	      }
102	      for (const [index, ref] of pluginRefs.entries()) {
103	        const endpointId = `ref_plugin_${processorIndex}_${index}`;
104	        const message =
105	          `Background processor configuration error: '${name}' could not resolve plugin reference '${ref}' HTTP endpoint.`;
106	        lines.push(
107	          `    const ${endpointId} = await _plugins.get(${
108	            JSON.stringify(ref)
109	          })?.getEndpoint('http');`,
110	        );
111	        lines.push(`    if (!${endpointId}) {`);
112	        lines.push(`      throw new Error(${JSON.stringify(message)});`);
113	        lines.push(`    }`);
114	      }
115	    }
116	
117	    // Register via addExecutable
