/**
 * @module
 *
 * Generator for `.helpers/register-background.mts` — registers background
 * processors (workers, sagas, triggers, benchmark) with the Aspire SDK
 * builder via `addExecutable()`.
 *
 * Each processor is registered using the CommunityToolkit beta NuGet's
 * `addExecutable(name, 'deno', workdir, ['run', ...perms, entrypoint])` method.
 * Telemetry-enabled entries receive the full executable OTEL env set via
 * `buildOtelEnvVars`; telemetry-disabled entries (e.g., benchmark) receive
 * explicit opt-out vars instead.
 *
 * Background processors do NOT cross-reference each other, so no two-pass
 * registration is needed.
 */

import type { RegisterBackgroundOptions } from '../types.ts';
import { extractSagaStoreBackend, fileHeader } from '../_utils.ts';
import { SCAFFOLD_ASPIRE_MODULES } from '../../../../constants/scaffold/scaffold-aspire.ts';
import { RESOURCE_DEFAULTS } from '@netscript/aspire/constants';
import { TEMPLATE_KEYS } from '../../../../assets/manifest.ts';
import { renderTemplateAssetSync } from '../../../../adapters/templates/template-asset.ts';
import { withDatabasePermissions } from './database-permissions.ts';

/**
 * Generates the register-background.mts file content.
 *
 * @param options - Background processor entries, version, and Deno defaults from parsed config
 * @returns Generated TypeScript source as a string
 */
export function generateRegisterBackground(options: RegisterBackgroundOptions): string {
  const { processors, version: _version, denoDefaults, databaseEngine } = options;
  const entries = Object.entries(processors);

  const registrationBlocks: string[] = [];

  for (const [processorIndex, [name, entry]] of entries.entries()) {
    const id = `bg_${processorIndex}`;
    const workdir = entry.Workdir ?? '.';
    const entrypoint = entry.Entrypoint ?? `${name}/runtime.ts`;
    const telemetry = entry.Telemetry !== false;
    const watchMode = entry.WatchMode ?? false;
    const entryPermissions = entry.Permissions
      ? withDatabasePermissions(entry.Permissions, databaseEngine)
      : undefined;
    const defaultPermissions = entryPermissions
      ? denoDefaults.Permissions
      : withDatabasePermissions(denoDefaults.Permissions, databaseEngine);
    const serviceRefs = [
      ...(entry.ServiceReferences ?? []),
    ];
    const pluginRefs = entry.PluginReferences ?? [];

    const lines: string[] = [];
    lines.push(`  // --- processor ${processorIndex} ---`);

    // Skip disabled entries
    lines.push(
      `  if (config.BackgroundProcessors[${JSON.stringify(name)}]?.Enabled !== false) {`,
    );

    // Resolve permissions — background uses --watch (NOT --watch-hmr)
    lines.push(`    const ${id}_perms = resolvePermissions(`);
    if (entryPermissions) {
      lines.push(`      ${JSON.stringify(entryPermissions)},`);
    } else {
      lines.push(`      undefined,`);
    }
    lines.push(`      ${JSON.stringify(defaultPermissions)},`);
    lines.push(`      ${watchMode},`);
    lines.push(`      '${RESOURCE_DEFAULTS.WatchFlag}',`);
    lines.push(`    );`);

    // Resolve working directory
    lines.push(
      `    const ${id}_workdir = resolveWorkspacePath(appHostDir, ${JSON.stringify(workdir)});`,
    );
    lines.push(
      `    const ${id}_bootstrapModule = new URL('../../services/_shared/plugin-service-context.ts', import.meta.url).href;`,
    );

    // Resolve every declared reference before registering the processor. A
    // declared reference is required configuration, so missing resources and
    // resources without an HTTP endpoint are equally fatal.
    if (serviceRefs.length > 0 || pluginRefs.length > 0) {
      lines.push(``);
      lines.push(`    // Declared reference preflight — fail before processor registration`);
      for (const [index, ref] of serviceRefs.entries()) {
        const endpointId = `ref_service_${processorIndex}_${index}`;
        const message =
          `Background processor configuration error: '${name}' could not resolve service reference '${ref}' HTTP endpoint.`;
        lines.push(
          `    const ${endpointId} = await _services.get(${
            JSON.stringify(ref)
          })?.getEndpoint('http');`,
        );
        lines.push(`    if (!${endpointId}) {`);
        lines.push(`      throw new Error(${JSON.stringify(message)});`);
        lines.push(`    }`);
      }
      for (const [index, ref] of pluginRefs.entries()) {
        const endpointId = `ref_plugin_${processorIndex}_${index}`;
        const message =
          `Background processor configuration error: '${name}' could not resolve plugin reference '${ref}' HTTP endpoint.`;
        lines.push(
          `    const ${endpointId} = await _plugins.get(${
            JSON.stringify(ref)
          })?.getEndpoint('http');`,
        );
        lines.push(`    if (!${endpointId}) {`);
        lines.push(`      throw new Error(${JSON.stringify(message)});`);
        lines.push(`    }`);
      }
    }

    // Register via addExecutable
    lines.push(
      `    const ${id} = builder.addExecutable(${
        JSON.stringify(name)
      }, 'deno', ${id}_workdir, ['run', '--minimum-dependency-age=0', '${RESOURCE_DEFAULTS.NodeModulesDirNoneFlag}', '${RESOURCE_DEFAULTS.UnstableWorkerOptionsFlag}', ...${id}_perms, ${
        JSON.stringify(entrypoint)
      }]);`,
    );
    if (isSagasBackgroundResource(name, entrypoint)) {
      lines.push(``);
      lines.push(`    // Saga supervisor health endpoint and real Aspire probe.`);
      lines.push(`    await ${id}.withHttpEndpoint({ env: 'PORT' });`);
      lines.push(
        `    await ${id}.withHttpHealthCheck({ path: '${RESOURCE_DEFAULTS.AppHealthCheckPath}', endpointName: '${RESOURCE_DEFAULTS.HttpEndpointName}' });`,
      );
    }
    lines.push(
      `    await ${id}.withEnvironment('NETSCRIPT_PLUGIN_SERVICE_BOOTSTRAP_MODULE', ${id}_bootstrapModule);`,
    );
    if (isTriggersBackgroundResource(name, entrypoint)) {
      lines.push(
        `    const ${id}_triggerRegistryModule = new URL('../../.netscript/generated/plugin-triggers/triggers.registry.ts', import.meta.url).href;`,
      );
      lines.push(
        `    await ${id}.withEnvironment('NETSCRIPT_TRIGGER_REGISTRY_MODULE', ${id}_triggerRegistryModule);`,
      );
    }

    const sagaStoreBackend = extractSagaStoreBackend(entry);
    if (sagaStoreBackend) {
      lines.push(
        `    await ${id}.withEnvironment('NETSCRIPT_SAGA_STORE', ${
          JSON.stringify(sagaStoreBackend)
        });`,
      );
    }

    // Telemetry env vars
    if (telemetry) {
      lines.push(``);
      lines.push(`    // OTEL telemetry (full executable env set)`);
      lines.push(
        `    const ${id}_otel = buildOtelEnvVars(${
          JSON.stringify(name)
        }, config.Version, 'executable');`,
      );
      lines.push(`    for (const [key, value] of Object.entries(${id}_otel)) {`);
      lines.push(`      await ${id}.withEnvironment(key, value);`);
      lines.push(`    }`);
      lines.push(
        `    await ${id}.withOtlpExporter({ protocol: OtlpProtocol.HttpProtobuf });`,
      );
    } else {
      lines.push(``);
      lines.push(`    // Telemetry disabled — opt out explicitly`);
      lines.push(`    await ${id}.withEnvironment('OTEL_DENO', 'false');`);
      lines.push(`    await ${id}.withEnvironment('OTEL_TRACES_SAMPLER', 'always_off');`);
    }

    // Concurrency
    if (entry.ConcurrencyEnvVar && entry.Concurrency) {
      lines.push(``);
      lines.push(`    // Concurrency`);
      lines.push(
        `    await ${id}.withEnvironment(${
          JSON.stringify(entry.ConcurrencyEnvVar)
        }, String(${entry.Concurrency}));`,
      );
    }

    // Infrastructure dependencies
    if (entry.RequiresDb) {
      lines.push(``);
      lines.push(`    // Database dependency`);
      lines.push(`    for (const [key, value] of Object.entries(databaseProviderEnv)) {`);
      lines.push(`      await ${id}.withEnvironment(key, value);`);
      lines.push(`    }`);
      lines.push(
        `    const ${id}_sqliteDatabase = config.PrimaryDatabase ? config.Databases[config.PrimaryDatabase] : undefined;`,
      );
      lines.push(
        `    if (${id}_sqliteDatabase?.Engine === 'Sqlite' && config.PrimaryDatabase) {`,
      );
      lines.push(
        `      const ${id}_sqliteUrl = buildSqliteDatabaseUrl(appHostDir, config.PrimaryDatabase, ${id}_sqliteDatabase.DatabaseName ?? \`\${config.PrimaryDatabase}.db\`);`,
      );
      lines.push(`      await ${id}.withEnvironment('DATABASE_URL', ${id}_sqliteUrl);`);
      lines.push(`      if (databaseEnvKey) {`);
      lines.push(`        await ${id}.withEnvironment(databaseEnvKey, ${id}_sqliteUrl);`);
      lines.push(`      }`);
      lines.push(`    } else if (infrastructure.primaryDatabase) {`);
      lines.push(
        `      let ${id}_databaseBinding = ${id}.withEnvironment('DATABASE_URL', infrastructure.primaryDatabase);`,
      );
      lines.push(`      if (databaseEnvKey) {`);
      lines.push(
        `        ${id}_databaseBinding = ${id}_databaseBinding.withEnvironment(databaseEnvKey, infrastructure.primaryDatabase);`,
      );
      lines.push(`      }`);
      lines.push(`      await ${id}_databaseBinding`);
      lines.push(`        .withReference(infrastructure.primaryDatabase)`);
      lines.push(`        .waitFor(infrastructure.primaryDatabase);`);
      lines.push(`    }`);
    }

    if (entry.RequiresKv) {
      lines.push(``);
      lines.push(`    // KV cache dependency`);
      lines.push(`    await _withCacheReference(${id}, infrastructure.primaryCacheWiring);`);
    }

    // Service references — wired via endpoint env vars (executable→executable)
    if (serviceRefs.length > 0) {
      lines.push(``);
      lines.push(`    // Service references — wired via endpoint env vars`);
      for (const [index, ref] of serviceRefs.entries()) {
        const endpointId = `ref_service_${processorIndex}_${index}`;
        lines.push(
          `    await ${id}.withEnvironment(${
            JSON.stringify(`services__${ref}__http__0`)
          }, ${endpointId});`,
        );
      }
    }

    // Plugin references — wired via endpoint env vars (executable→executable)
    if (pluginRefs.length > 0) {
      lines.push(``);
      lines.push(`    // Plugin references — wired via endpoint env vars`);
      for (const [index, ref] of pluginRefs.entries()) {
        const endpointId = `ref_plugin_${processorIndex}_${index}`;
        lines.push(
          `    await ${id}.withEnvironment(${
            JSON.stringify(`services__${ref}__http__0`)
          }, ${endpointId});`,
        );
      }
    }

    lines.push(``);
    lines.push(`    backgroundProcessors.set(${JSON.stringify(name)}, ${id});`);
    lines.push(`  }`);

    registrationBlocks.push(lines.join('\n'));
  }

  return renderTemplateAssetSync(TEMPLATE_KEYS.generatedAspireHelpersGenerateRegisterBackground1, {
    __slot0__: String(fileHeader('register-background.mts')),
    __slot1__: String(SCAFFOLD_ASPIRE_MODULES.SDK_IMPORT_FROM_HELPERS),
    __slot2__: String(SCAFFOLD_ASPIRE_MODULES.ASPIRE_COMPAT_IMPORT),
    __slot3__: String(SCAFFOLD_ASPIRE_MODULES.ASPIRE_COMPAT_IMPORT),
    __slot4__: String(
      registrationBlocks.length > 0
        ? registrationBlocks.join('\n\n')
        : '  // No background processors configured',
    ),
  });
}

function isTriggersBackgroundResource(name: string, entrypoint: string): boolean {
  return name === 'triggers' || entrypoint === 'triggers/runtime.ts';
}

function isSagasBackgroundResource(name: string, entrypoint: string): boolean {
  return name === 'sagas' || entrypoint === 'sagas/runtime.ts';
}

